      }));
    }

    waitForAll(futures);
    futures.clear();
    pool.shutdown();
    THREAD_ID.set(0);

    // write to file
    for (final ClassContext cls : toDump) {
      if (cls.classContent != null) {
        sink.acceptClass(cls.cl.qualifiedName, cls.entryName, cls.classContent, cls.mapping);
      }
    }

