        future.get();
      } catch (ExecutionException e) {
        if (e.getCause() instanceof CancelationManager.CanceledException) {
          throw (CancelationManager.CanceledException) e.getCause();
        } else {
          throw new RuntimeException(e);
        }
      } catch (InterruptedException e) {
        throw new RuntimeException(e);
      }
    }
  }

