  }

  public boolean isRoot() {
    return this.root;
  }

  public boolean isLazy() {
    return !this.own && this.source.isLazy();
  }

  void close() throws Exception {
    if (this.source instanceof AutoCloseable) {
      ((AutoCloseable) this.source).close();
    }
    this.clear();
  }

