  public @Nullable StructClass getClass(String name) {
    if (name == null) {
      return null;
    }
    synchronized (this.resolutionLock) {
      StructClass cached = this.classes.get(name);
      if (cached != null) {
        return cached == getSentinel() ? null : cached;
      }

      Selection selection = resolveSelection(name);
      if (selection == null) {
        this.classes.put(name, getSentinel());
        return null;
      }

      DecompilerContext.getLogger().writeMessage("Loading Class: " + name + " from " + originName(selection.origin), IFernflowerLogger.Severity.INFO);
      try {
        StructClass clazz = StructClass.create(new DataInputFullStream(selection.bytes), selection.origin.isOwn());
        this.classes.put(name, clazz);
        if (!name.equals(clazz.qualifiedName)) {
          this.badlyPlacedClasses.put(name, clazz.qualifiedName);
          this.classes.put(clazz.qualifiedName, clazz);
          this.classes.remove(name);
        }
        return clazz;
      } catch (IOException exception) {
        throw new UncheckedIOException("Failed to read class " + name + " from " + originName(selection.origin), exception);
      }
    }
  }

