      this.candidatesByClassName.clear();
      this.originOrder.clear();
      this.nextOrigin = 0;
      this.abstractNames.clear();

      final List<ContextUnit> units = List.copyOf(this.units);
      this.units.clear();
      this.lazyUnits.clear();
      for (ContextUnit unit : units) {
