  private void initUnit(final ContextUnit unit) {
    DecompilerContext.getLogger().writeMessage("Scanning classes from " + unit.getName(), IFernflowerLogger.Severity.INFO);
    for (final String clazz : unit.getClassNames()) {
      List<ContextUnit> candidates = this.candidatesByClassName.computeIfAbsent(clazz, ignored -> new ArrayList<>());
      if (!candidates.contains(unit)) {
        candidates.add(unit);
      }
      DecompilerContext.getLogger().writeMessage("    " + clazz, IFernflowerLogger.Severity.TRACE);
    }

    for (final IContextSource child : unit.getChildContexts()) {
      this.addSpace(child, unit.isOwn(), false);
    }
  }

  private @Nullable Selection resolveSelection(String name) {
    Optional<Selection> cached = this.selections.get(name);
    if (cached != null) {
      return cached.orElse(null);
    }

    List<Candidate> candidates = getCandidates(name);
    if (candidates.isEmpty()) {
      this.selections.put(name, Optional.empty());
      return null;
    }

    List<Candidate> ownCandidates = candidates.stream().filter(candidate -> candidate.origin.isOwn()).toList();
    List<Candidate> eligible = ownCandidates.isEmpty() ? candidates : ownCandidates;
    Family family = this.familiesByMember.get(name);

    if (family == null && ownCandidates.size() > 1) {
      family = activateFamily(name, ownCandidates);
      Optional<Selection> activatedSelection = this.selections.get(name);
      if (activatedSelection != null) {
        return activatedSelection.orElse(null);
      }
    }

    Selection selection;
    if (family != null && !ownCandidates.isEmpty()) {
      validateErrorStrategy(name, ownCandidates, family.root);
      ContextUnit familyAnchor = family.anchor;
      Candidate anchored = ownCandidates.stream().filter(candidate -> candidate.origin == familyAnchor).findFirst().orElse(null);
      if (anchored == null) {
        throw familyCoherenceFailure(family, name, ownCandidates);
      }
      warnIfDiffering(name, ownCandidates, anchored, family.root);
      selection = new Selection(anchored.origin, anchored.bytes);
    } else {
      String familyRoot = family == null && eligible.size() > 1 ? discoverFamily(name, false).root : family == null ? name : family.root;
      selection = choose(name, eligible, familyRoot);
    }

    this.selections.put(name, Optional.of(selection));
    return selection;
  }

  private Family activateFamily(String duplicateName, List<Candidate> duplicateCandidates) {
    FamilyShape shape = discoverFamily(duplicateName);
    Family existing = shape.members.stream().map(this.familiesByMember::get).filter(Objects::nonNull).findFirst().orElse(null);
    if (existing != null) {
      for (String member : shape.members) {
        this.familiesByMember.put(member, existing);
      }
      return existing;
    }

    List<Candidate> rootCandidates = getCandidates(shape.root).stream().filter(candidate -> candidate.origin.isOwn()).toList();
    Selection anchorSelection;
    if (!rootCandidates.isEmpty()) {
      anchorSelection = choose(shape.root, rootCandidates, shape.root);
      this.selections.put(shape.root, Optional.of(anchorSelection));
    } else {
      anchorSelection = choose(duplicateName, duplicateCandidates, shape.root);
      this.selections.put(duplicateName, Optional.of(anchorSelection));
    }

    Family family = new Family(shape.root, anchorSelection.origin, shape.members);
    for (String member : shape.members) {
      this.familiesByMember.put(member, family);
    }
    return family;
  }

  private FamilyShape discoverFamily(String start) {
    return discoverFamily(start, true);
  }

  private FamilyShape discoverFamily(String start, boolean ownOnly) {
    Map<String, String> parents = new LinkedHashMap<>();
    Map<String, Set<String>> links = new LinkedHashMap<>();
    Set<String> inspected = new HashSet<>();
    Deque<String> pending = new ArrayDeque<>();
    pending.add(start);

    while (!pending.isEmpty()) {
      String name = pending.removeFirst();
      if (!inspected.add(name)) {
        continue;
      }

      for (Candidate candidate : getCandidates(name)) {
        if (ownOnly && !candidate.origin.isOwn()) {
          continue;
        }
        StructClass metadata = parseMetadata(name, candidate);
        StructInnerClassesAttribute innerClasses = metadata.getAttribute(StructGeneralAttribute.ATTRIBUTE_INNER_CLASSES);
        if (innerClasses != null) {
          for (StructInnerClassesAttribute.Entry entry : innerClasses.getEntries()) {
            pending.addLast(entry.innerName);
            if (entry.enclosingName != null) {
              addFamilyLink(entry.innerName, entry.enclosingName, parents, links, pending);
            }
          }
        }
        StructEnclosingMethodAttribute enclosingMethod = metadata.getAttribute(StructGeneralAttribute.ATTRIBUTE_ENCLOSING_METHOD);
        if (enclosingMethod != null) {
          addFamilyLink(metadata.qualifiedName, enclosingMethod.getClassName(), parents, links, pending);
        }
      }
    }

    Set<String> members = new LinkedHashSet<>();
    pending.add(start);
    while (!pending.isEmpty()) {
      String name = pending.removeFirst();
      if (members.add(name)) {
        pending.addAll(links.getOrDefault(name, Set.of()));
      }
    }

    String root = start;
    Set<String> seen = new HashSet<>();
    while (seen.add(root) && parents.containsKey(root)) {
      root = parents.get(root);
    }
    members.add(root);
    return new FamilyShape(root, Set.copyOf(members));
  }

  private static void addFamilyLink(String child, String parent, Map<String, String> parents,
                                    Map<String, Set<String>> links, Deque<String> pending) {
    parents.putIfAbsent(child, parent);
    links.computeIfAbsent(child, ignored -> new LinkedHashSet<>()).add(parent);
    links.computeIfAbsent(parent, ignored -> new LinkedHashSet<>()).add(child);
    pending.addLast(child);
    pending.addLast(parent);
  }

  private StructClass parseMetadata(String name, Candidate candidate) {
    try {
      return StructClass.create(new DataInputFullStream(candidate.bytes), candidate.origin.isOwn());
    } catch (IOException exception) {
      throw new UncheckedIOException("Failed to inspect class family metadata for " + name + " from " + originName(candidate.origin), exception);
    }
  }

  private List<Candidate> getCandidates(String name) {
    List<ContextUnit> eager = this.candidatesByClassName.getOrDefault(name, List.of());
    List<Candidate> result = new ArrayList<>();
    for (ContextUnit unit : this.units) {
      boolean listed = eager.contains(unit);
      if (!listed && !unit.isLazy()) {
        continue;
      }
      byte[] bytes = readClassBytes(unit, name);
      if (bytes != null) {
        result.add(new Candidate(unit, bytes));
      }
    }
    return result;
  }

  private byte @Nullable [] readClassBytes(ContextUnit unit, String name) {
    Probe probe = new Probe(unit, name);
    Optional<byte[]> cached = this.probes.get(probe);
    if (cached != null) {
      return cached.orElse(null);
    }
    try {
      byte[] bytes = unit.getClassBytes(name);
      this.probes.put(probe, Optional.ofNullable(bytes));
      return bytes;
    } catch (IOException exception) {
      DecompilerContext.getLogger().writeMessage("Failed to read class " + name + " from " + originName(unit), IFernflowerLogger.Severity.ERROR, exception);
      this.probes.put(probe, Optional.empty());
      return null;
    }
  }

  private Selection choose(String name, List<Candidate> candidates, String familyRoot) {
    validateErrorStrategy(name, candidates, familyRoot);
    Candidate selected = this.duplicateClassStrategy == DuplicateClassStrategy.LAST
      ? candidates.get(candidates.size() - 1)
      : candidates.get(0);
    warnIfDiffering(name, candidates, selected, familyRoot);
    return new Selection(selected.origin, selected.bytes);
  }

  private void validateErrorStrategy(String name, List<Candidate> candidates, String familyRoot) {
    if (this.duplicateClassStrategy != DuplicateClassStrategy.ERROR || !hasDifferingBytes(candidates)) {
      return;
    }
    throw new IllegalStateException(
      "Conflicting class '" + name + "' with metadata family root '" + familyRoot +
        "' in highest-precedence origins: " + candidates.stream().map(candidate -> originName(candidate.origin)).collect(Collectors.joining(", "))
    );
  }

  private void warnIfDiffering(String name, List<Candidate> candidates, Candidate selected, String familyRoot) {
    if (this.duplicateClassStrategy == DuplicateClassStrategy.ERROR || !hasDifferingBytes(candidates)) {
      return;
    }
    String ignored = candidates.stream().filter(candidate -> candidate != selected)
      .map(candidate -> originName(candidate.origin)).collect(Collectors.joining(", "));
    DecompilerContext.getLogger().writeMessage(
      "Duplicate class '" + name + "' resolved with strategy '" + this.duplicateClassStrategy.optionValue() +
        "': selected " + originName(selected.origin) + "; ignored origins in registration order: " + ignored +
        "; metadata family root: '" + familyRoot + "'",
      IFernflowerLogger.Severity.WARN
    );
  }

  private static boolean hasDifferingBytes(List<Candidate> candidates) {
    if (candidates.size() < 2) {
      return false;
    }
    byte[] first = candidates.get(0).bytes;
    return candidates.stream().skip(1).anyMatch(candidate -> !Arrays.equals(first, candidate.bytes));
  }

  private IllegalStateException familyCoherenceFailure(Family family, String member, List<Candidate> alternatives) {
    return new IllegalStateException(
      "Class family '" + family.root + "' member '" + member + "' is anchored to " + originName(family.anchor) +
        " but is available only from alternative own origins: " + alternatives.stream()
        .map(candidate -> originName(candidate.origin)).collect(Collectors.joining(", "))
    );
  }

  private boolean isSelectedOrigin(String name, ContextUnit unit) {
    synchronized (this.resolutionLock) {
      Selection selection = resolveSelection(name);
      return selection != null && selection.origin == unit && unit.isOwn();
    }
  }

  private String originName(ContextUnit unit) {
    return "'" + unit.getName() + "' [origin " + (this.originOrder.get(unit) + 1) + "]";
  }

  private void clearResolutionState(boolean clearProbes) {
    this.classes.clear();
    this.badlyPlacedClasses.clear();
    this.selections.clear();
    this.familiesByMember.clear();
    if (clearProbes) {
      this.probes.clear();
    }
  }

  // return (valclass instanceof reflcass)
  public boolean instanceOf(String valclass, String refclass) {
    if (refclass == null || valclass == null) {
      return false;
    }

    if (valclass.equals(refclass)) {
      return true;
    }

    StructClass cl = this.getClass(valclass);
    // Don't know what we are? We must at least be an object.
    if ((cl == null || cl.superClass == null) && refclass.equals("java/lang/Object")) {
      return true;
    }

    if (cl == null) {
      return false;
    }

    if (cl.superClass != null && this.instanceOf(cl.superClass.getString(), refclass)) {
      return true;
    }

    for (int iface : cl.getInterfaces()) {
      if (this.instanceOf(cl.getPool().getPrimitiveConstant(iface).getString(), refclass)) {
        return true;
      }
    }

    return false;
  }

