  public @Nullable StructClass findCommonAncestor(String classA, String classB) {
  public @Nullable StructClass findCommonAncestor(String classA, String classB) {
    StructClass a = this.getClass(classA);
    StructClass b = this.getClass(classB);

    if (a == null || b == null) {
